using TerraRuntime.Contracts.Gameplay;

namespace TerraRuntime.Gameplay.Items;

/// <summary>Clean numeric metadata from original Main.Initialize_Items and ItemID.Sets.</summary>
public static class VanillaFurnitureItemFacts1458
