    public static bool TryGetLegacyArmor(int row, int armorSlot, out ItemTypeId item)
    {
        item = default;
        ReadOnlySpan<short> table = row switch { 0 => Head, 1 => Body, 2 => Legs, _ => [] };
        if ((uint)armorSlot >= (uint)table.Length) return false;
        return VanillaItemIds.TryCreate(table[armorSlot], out item);
    }
    // Current canonical world contents are admitted. A raw legacy alias or
    // deprecated identity needs the separate load-normalization source context.
    public static bool IsCanonicalItemOrAir(ItemTypeId item) => VanillaItemUseStyleFacts1458.TryGet(item, out _);

    public static bool IsNoGravity(ItemTypeId item) => Array.IndexOf(NoGravity, (ushort)item.Value) >= 0;

    public static bool TryGetNextDollPose(byte current, ItemTypeId misc, short stack, out byte pose)
    {
        pose = unchecked((byte)(current + 1));
        if (pose <= 3) return true;
        if (!VanillaItemUseStyleFacts1458.TryResolveSourceMetadata(misc, out var canonical, out byte style)) return false;
        bool valid = stack > 0 && !canonical.IsNone && (style switch
        {
            1 or 5 or 13 => pose is >= 4 and <= 8,
            12 => pose is >= 4 and <= 6,
            2 or 3 or 4 or 6 or 7 or 8 or 9 or 11 or 14 or 15 => pose == 4,
            _ => false
        });
        if (!valid) pose = 0;
        return true;
    }
